mapper.select:
SELECT aan.assignee_id,aan.assignee_code,aan.assignee_code_at, ( select distinct su.USER_NAME from sys_user su , sys_user_allocation sua , fnd_employee_assigns fea , fnd_employee fe where su.USER_ID = sua.user_id and sua.employee_assign_id = fea.employee_assign_id and fe.employee_id = fea.employee_id and fe.employee_code = aan.assignee_code )as user_name, ( select distinct su.USER_NAME from sys_user su , sys_user_allocation sua , fnd_employee_assigns fea , fnd_employee fe where su.USER_ID = sua.user_id and sua.employee_assign_id = fea.employee_assign_id and fe.employee_id = fea.employee_id and fe.employee_code = aan.assignee_code_at )as user_name_at from act_assignee_node aan where 1 = 1
and aan.assignee_type =#{assigneeType}
and aan.project_id =#{projectId}
and aan.project_document_category=#{projectDocumentCategory}
and aan.process_instance_id=#{processInstanceId}

update act_assignee_node
set assignee_code = #{assigneeCode},assignee_code_at = #{assigneeCodeAt}
where
1 = 1

    and assignee_type =#{assigneeType}


    and project_id =#{projectId}


    and project_document_category=#{projectDocumentCategory}
